mapper.update:
UPDATE post
SET status='SCHEDULED', published_at=#{publishAt}, updated_by=#{ownerId}, version=version+1
WHERE id=#{id} AND deleted=0 AND version=#{version}

UPDATE post
SET status='DRAFT', published_at=NULL, updated_by=#{ownerId}, version=version+1
WHERE id=#{id} AND deleted=0 AND status='SCHEDULED' AND version=#{version}

mapper.insert:
INSERT INTO post_autosave(id,post_id,post_type,payload_json,base_version,saved_at,updated_by)
SELECT #{autosave.id},p.id,#{autosave.postType},#{autosave.payloadJson},#{autosave.baseVersion},UTC_TIMESTAMP(3),#{autosave.updatedBy}
FROM post p
WHERE p.id=#{autosave.postId} AND p.type=#{autosave.postType}
  AND p.deleted=0 AND p.version=#{autosave.baseVersion}
ON DUPLICATE KEY UPDATE
  post_type=VALUES(post_type),payload_json=VALUES(payload_json),
  base_version=VALUES(base_version),saved_at=VALUES(saved_at),updated_by=VALUES(updated_by)

mapper.select:
SELECT id,post_id AS postId,version_no AS versionNo,post_type AS postType,
       summary,created_at AS createdAt
FROM post_version WHERE post_id=#{postId}
ORDER BY version_no DESC,id DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE post_media
SET deleted=0,deleted_at=NULL
WHERE post_id=#{postId} AND deleted=1
  AND deleted_at=(SELECT latest.deleted_at FROM (
      SELECT MAX(deleted_at) AS deleted_at FROM post_media WHERE post_id=#{postId}
  ) latest)

mapper.select:
SELECT * FROM post
WHERE status='SCHEDULED' AND deleted=0 AND published_at<=UTC_TIMESTAMP(3)
ORDER BY published_at,id LIMIT #{limit}

mapper.update:
UPDATE post SET status='PUBLISHED',version=version+1
WHERE id=#{id} AND status='SCHEDULED' AND deleted=0
  AND published_at<=UTC_TIMESTAMP(3) AND version=#{version}
